      "kind": "server.py",
      "language": "python",
      "source": "import http.server
import json
from urllib.parse import urlparse

class TaskHandler(http.server.BaseHTTPRequestHandler):
    # In-memory storage for tasks and auto-incrementing ID
    tasks = {}
    next_id = 1
    VALID_STATUSES = ['pendiente', 'en progreso', 'completada']

    def do_GET(self):
        parsed_path = urlparse(self.path)
        if parsed_path.path == '/tasks':
            # Return all tasks
            response = list(self.tasks.values())
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(response).encode())
        elif parsed_path.path.startswith('/tasks/'):
            task_id = parsed_path.path.split('/')[-1]
            if task_id in self.tasks:
                response = self.tasks[task_id]
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps(response).encode())
            else:
                self.send_error_response(404, 'Task not found')
        else:
            self.send_error_response(404, 'Endpoint not found')

    def do_POST(self):
        if self.path == '/tasks':
            content_length = int(self.headers.get('Content-Length', 0))
            post_data = self.rfile.read(content_length)
            try:
                data = json.loads(post_data)
                # Validate required fields
                if 'title' not in data or 'description' not in data or 'status' not in data:
                    self.send_error_response(400, 'Missing required fields: title, description, status')
                    return
                if data['status'] not in self.VALID_STATUSES:
                    self.send_error_response(400, 'Invalid status value. Must be one of: ' + ', '.join(self.VALID_STATUSES))
                    return
                # Set id and create task
                task_id = str(self.next_id)
                self.next_id += 1
                task = {
                    'id': task_id,
                    'title': data['title'],
                    'description': data['description'],
                    'status': data['status']
                }
                self.tasks[task_id] = task
                self.send_response(201)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps(task).encode())
            except json.JSONDecodeError:
                self.send_error_response(400, 'Invalid JSON')
        else:
            self.send_error_response(404, 'Endpoint not found')

    def do_PUT(self):
        parsed_path = urlparse(self.path)
        if parsed_path.path.startswith('/tasks/'):
            task_id = parsed_path.path.split('/')[-1]
            if task_id in self.tasks:
                content_length = int(self.headers.get('Content-Length', 0))
                put_data = self.rfile.read(content_length)
                try:
                    data = json.loads(put_data)
                    # Validate required fields for full update
                    if 'title' not in data or 'description' not in data or 'status' not in data:
                        self.send_error_response(400, 'Missing required fields: title, description, status')
                        return
                    if data['status'] not in self.VALID_STATUSES:
                        self.send_error_response(400, 'Invalid status value. Must be one of: ' + ', '.join(self.VALID_STATUSES))
                        return
                    # Update task (full replacement)
                    self.tasks[task_id] = {
                        'id': task_id,
                        'title': data['title'],
                        'description': data['description'],
                        'status': data['status']
                    }
                    self.send_response(200)
                    self.send_header('Content-Type', 'application/json')
                    self.end_headers()
                    self.wfile.write(json.dumps(self.tasks[task_id]).encode())
                except json.JSONDecodeError:
                    self.send_error_response(400, 'Invalid JSON')
            else:
                self.send_error_response(404, 'Task not found')
        else:
            self.send_error_response(404, 'Endpoint not found')

    def do_DELETE(self):
        parsed_path = urlparse(self.path)
        if parsed_path.path.startswith('/tasks/'):
            task_id = parsed_path.path.split('/')[-1]
            if task_id in self.tasks:
                del self.tasks[task_id]
                self.send_response(204)
                self.end_headers()
            else:
                self.send_error_response(404, 'Task not found')
        else:
            self.send_error_response(404, 'Endpoint not found')

    def send_error_response(self, code, message):
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'error': message}).encode())

if __name__ == '__main__':
    server_address = ('', 8000)  # Localhost, port 8000
    httpd = http.server.HTTPServer(server_address, TaskHandler)
    print('Starting server on port 8000...')
    httpd.serve_forever()"
